  const tokens = fs.readFileSync(0, 'utf8').split(/\s+/);
  let pi = 0;
  function rd() {
    while (tokens[pi] === '') pi++;
    return +tokens[pi++];
  }

  const N = rd(), M = rd(), K = rd();
  const P = new Int32Array(K + 1);
  for (let i = 1; i <= K; i++) P[i] = rd();

  const EV = new Int32Array(M), EU = new Int32Array(M), ET = new Int32Array(M);
  for (let j = 0; j < M; j++) { EV[j] = rd(); EU[j] = rd(); ET[j] = rd(); }
  const A = rd(), B = rd();

  // counting sort estável das arestas por sistema
  const start = new Int32Array(K + 2);
  for (let j = 0; j < M; j++) start[ET[j] + 1]++;
  for (let t = 1; t <= K + 1; t++) start[t] += start[t - 1];
  const ptr = start.slice();
  const sV = new Int32Array(M), sU = new Int32Array(M);
  for (let j = 0; j < M; j++) {
    const q = ptr[ET[j]]++;
    sV[q] = EV[j]; sU[q] = EU[j];
  }

  const EMAX = 4 * M + 8;
  const eF = new Int32Array(EMAX), eT = new Int32Array(EMAX), eW = new Int32Array(EMAX);
  let eCnt = 0;

  let nextId = N;
  const pa = new Int32Array(N + 1);
  const cid = new Int32Array(N + 1);
  const sid = new Int32Array(N + 1);
  let stamp = 0;
  const touched = new Int32Array(2 * M + 2);

  function find(x) {
    let r = x;
    while (pa[r] !== r) r = pa[r];
    while (pa[x] !== r) { const nx = pa[x]; pa[x] = r; x = nx; }
    return r;
  }

  for (let t = 1; t <= K; t++) {
    const s = start[t], e = start[t + 1];
    if (s === e) continue;
    stamp++;
    let tLen = 0;
    for (let j = s; j < e; j++) {
      const v = sV[j];
      if (pa[v] === 0) { pa[v] = v; touched[tLen++] = v; }
      const u = sU[j];
      if (pa[u] === 0) { pa[u] = u; touched[tLen++] = u; }
      const rv = find(v), ru = find(u);
      if (rv !== ru) pa[ru] = rv;
    }
    for (let i = 0; i < tLen; i++) {
      const r = find(touched[i]);
      if (sid[r] !== stamp) { sid[r] = stamp; cid[r] = ++nextId; }
    }
    const pt = P[t];
    for (let i = 0; i < tLen; i++) {
      const v = touched[i];
      const c = cid[find(v)];
      eF[eCnt] = v; eT[eCnt] = c; eW[eCnt] = pt; eCnt++;
      eF[eCnt] = c; eT[eCnt] = v; eW[eCnt] = 0; eCnt++;
    }
    for (let i = 0; i < tLen; i++) pa[touched[i]] = 0;
  }

  const V = nextId, E = eCnt;
  const head = new Int32Array(V + 1);
  for (let i = 0; i < E; i++) head[eF[i] + 1]++;
  for (let v = 0; v < V; v++) head[v + 1] += head[v];
  const cur = head.slice(0, V);
  const adjTo = new Int32Array(E), adjW = new Int32Array(E);
  for (let i = 0; i < E; i++) {
    const f = eF[i];
    adjTo[cur[f]] = eT[i]; adjW[cur[f]] = eW[i]; cur[f]++;
  }

  const dist = new Float64Array(V + 1).fill(Infinity);
  dist[A] = 0;

  const cap = E + 16;
  const hD = new Float64Array(cap), hN = new Int32Array(cap);
  let hn = 0;
  function push(d, v) {
    let i = hn++;
    hD[i] = d; hN[i] = v;
    while (i > 0) {
      const par = (i - 1) >> 1;
      if (hD[par] <= hD[i]) break;
      const td = hD[par]; hD[par] = hD[i]; hD[i] = td;
      const tn = hN[par]; hN[par] = hN[i]; hN[i] = tn;
      i = par;
    }
  }
  push(0, A);

  let ans = -1;
  while (hn > 0) {
    const d = hD[0], v = hN[0];
    hn--;
    if (hn > 0) {
      hD[0] = hD[hn]; hN[0] = hN[hn];
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        if (l >= hn) break;
        let s = l;
        const r = l + 1;
        if (r < hn && hD[r] < hD[l]) s = r;
        if (hD[s] >= hD[i]) break;
        const td = hD[s]; hD[s] = hD[i]; hD[i] = td;
        const tn = hN[s]; hN[s] = hN[i]; hN[i] = tn;
        i = s;
      }
    }
    if (d > dist[v]) continue;
    if (v === B) { ans = d; break; }
    const e0 = head[v], e1 = head[v + 1];
    for (let e = e0; e < e1; e++) {
      const nt = adjTo[e];
      const nd = d + adjW[e];
      if (nd < dist[nt]) { dist[nt] = nd; push(nd, nt); }
    }
  }

  console.log(ans);
}

main();
